-- CI-042 v2.2 MANDATORY POST-CHECK (read-only). If any row has pass = false: run 20261027092000_ci042v22_ROLLBACK.sql (default mode B) and re-run the pre-check. Baseline literals: production 27 Oct 2026 17:00 IST.
with cols as (select c.oid::regclass::text v, string_agg(a.attnum||':'||a.attname||':'||format_type(a.atttypid,a.atttypmod), ',' order by a.attnum) s
                from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
               where c.oid in ('costing.v_costing_period_run_status'::regclass,'public.v_costing_pricing_period_run_status'::regclass) group by 1),
chk(check_name, expected, actual) as (
  select 'Q01 combined fingerprint 119/122/143', '3e5515ed97189b747ea3a8d18c3f4411', (select md5(string_agg(md5(costing.fn_compute_run_fingerprint(r)::text),'|' order by r)) from unnest(array[119,122,143]) r)
  union all select 'Q02 queued/running runs', '0', (select count(*)::text from costing.costing_refresh_run where overall_status in ('QUEUED','RUNNING'))
  union all select 'Q03 runs count/max', '118/143', (select count(*)||'/'||max(id) from costing.costing_refresh_run)
  union all select 'Q04 audit rows count/max id', '17/21', (select count(*)||'/'||max(audit_id) from costing.cost_period_governance_audit)
  union all select 'Q05 designation rows count/max id', '9/11', (select count(*)||'/'||max(id) from costing.costing_run_designation)
  union all select 'Q06 fingerprint rows count/max id', '28/30', (select count(*)||'/'||max(id) from costing.costing_run_fingerprint)
  union all select 'Q07 effective designations', '119=REFERENCE,122=APPROVED,128=REVOKED,136=REVOKED,140=REVOKED,143=APPROVED', (select string_agg(refresh_run_id||'='||designation, ',' order by refresh_run_id) from costing.v_costing_run_effective_designation)
  union all select 'Q08 periods', '2026-03-01:OPEN:2026-03-31 2026-06-01:OPEN:2026-06-30 2026-07-01:OPEN:2026-07-22 2026-08-01:OPEN:2026-08-07 2026-09-01:LOCKED:2026-09-10 2026-10-01:OPEN:2026-10-22', (select string_agg(period_start||':'||status||':'||valuation_date, ' ' order by period_start) from costing.cost_periods)
  union all select 'Q09 lock is state-only (no align / mismatch)', 'true', (select (prosrc not ilike '%ALIGN_AT_LOCK%' and prosrc not ilike '%W2_LOCK_VALUATION_DATE_MISMATCH%')::text from pg_proc where oid='public.rpc_costing_lock_period(date,text,text)'::regprocedure)
  union all select 'Q10 old finalise refuses (route error)', 'true', (select (prosrc like '%W2_USE_NEW_APPROVAL_ROUTE%')::text from pg_proc where oid='public.rpc_costing_finalize_monthend_run(bigint,text,text)'::regprocedure)
  union all select 'Q11 batch lock has v2.2 validation codes', 'true', (select (prosrc like '%W2_BATCH_NULL_ARRAY%' and prosrc like '%W2_BATCH_MIXED_QUARTER%' and prosrc like '%W2_BATCH_UNKNOWN_MONTH%' and prosrc like '%W2_BATCH_DUPLICATE_MONTH%')::text from pg_proc where oid='public.rpc_costing_lock_periods_for_close(date[],text,text)'::regprocedure)
  union all select 'Q12 CI-040 dependency fn_w2_approve_unified present', 'true', (to_regprocedure('costing.fn_w2_approve_unified(bigint,text,text,bigint,boolean,text)') is not null)::text
  union all select 'Q13 ACL + SECURITY DEFINER + owner: lock, finalise, batch lock, preview finalise', 'postgres true {postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres} x4', (select max(proowner::regrole||' '||prosecdef||' '||proacl::text)||' x'||count(*) from pg_proc where oid in ('public.rpc_costing_lock_period(date,text,text)'::regprocedure,'public.rpc_costing_finalize_monthend_run(bigint,text,text)'::regprocedure,'public.rpc_costing_lock_periods_for_close(date[],text,text)'::regprocedure,'public.rpc_costing_finalize_monthend_run_with_preview(bigint,text,text,bigint,boolean)'::regprocedure) having count(distinct proowner::regrole||' '||prosecdef||' '||proacl::text)=1)
  union all select 'Q14 ACL views: status costing | status public | run-display costing | run-display public', '{postgres=arwdDxtm/postgres,service_role=r/postgres} | {postgres=arwdDxtm/postgres,authenticated=r/postgres,service_role=arwdDxtm/postgres} | {postgres=arwdDxtm/postgres,service_role=r/postgres} | {postgres=arwdDxtm/postgres,authenticated=r/postgres,service_role=r/postgres}', (select string_agg(coalesce(relacl::text,'null'), ' | ' order by o) from (values (1,'costing.v_costing_period_run_status'::regclass),(2,'public.v_costing_pricing_period_run_status'::regclass),(3,'costing.v_costing_run_display_status'::regclass),(4,'public.v_costing_pricing_run_display_status'::regclass)) v(o,r) join pg_class c on c.oid=v.r)
  union all select 'Q14b anon has no privilege on any CI-042 object', 'false', (has_function_privilege('anon','public.rpc_costing_lock_periods_for_close(date[],text,text)','execute') or has_function_privilege('anon','public.rpc_costing_finalize_monthend_run_with_preview(bigint,text,text,bigint,boolean)','execute') or has_function_privilege('anon','public.rpc_costing_lock_period(date,text,text)','execute') or has_table_privilege('anon','public.v_costing_pricing_run_display_status','select,insert,update,delete') or has_table_privilege('anon','public.v_costing_pricing_period_run_status','select'))::text
  union all select 'Q15 status views: original 18 columns identical (name/type/order) + 9 appended, both views identical', '1:period_start:date,2:period_status:text,3:valuation_date:date,4:valuation_date_status:text,5:displayed_run_id:bigint,6:displayed_run_basis:text,7:approved_run_id:bigint,8:approved_at:timestamp with time zone,9:approved_by:text,10:latest_success_run_id:bigint,11:latest_success_finished_at:timestamp with time zone,12:newer_draft_run_id:bigint,13:active_run_id:bigint,14:active_run_status:text,15:active_run_stage:text,16:display_state:text,17:display_label:text,18:is_latest_approved_period:boolean,19:approved_run_valuation_date:date,20:official_valuation_date:date,21:latest_draft_run_id:bigint,22:latest_draft_valuation_date:date,23:newer_draft_count:bigint,24:superseded_run_ids:bigint[],25:superseded_run_count:integer,26:pricing_use_label:text,27:display_label_v2:text x2', (select max(s)||' x'||count(distinct v) from cols having count(distinct s)=1)
  union all select 'Q16 policy record COSTING-LOCK-BEFORE-CLOSE-POLICY-2026-10-26 (exact wording)', 'COSTING-LOCK-BEFORE-CLOSE-POLICY-2026-10-26 (CI-042 v2; D1, D7): approval alone freezes the numbers; lock months only to prepare a formal Close, normally in quarterly batches (all-or-nothing). Lock changes only the month state; the official date is the approved run''s own date (derived, never moved). Month-end finalise approves with a preview acknowledgement and does not lock.', obj_description('public.rpc_costing_lock_periods_for_close(date[],text,text)'::regprocedure,'pg_proc')
  union all select 'Q16b October official date / September official+stored', '2026-10-22 | 2026-09-10/2026-09-10', (select official_valuation_date::text from costing.v_costing_period_run_status where period_start='2026-10-01')||' | '||(select official_valuation_date||'/'||valuation_date from costing.v_costing_period_run_status where period_start='2026-09-01')
  union all select 'Q16c per-run labels', '119=Reference,122=Approved,128=Superseded,136=Superseded,140=Superseded,143=Approved', (select string_agg(refresh_run_id||'='||display_status, ',' order by refresh_run_id) from costing.v_costing_run_display_status where refresh_run_id in (119,122,128,136,140,143))
  union all select 'Q17 cron 66/67/68 active + command md5', '66:true:0045bba6068cf31ac53852d6b743a745 67:true:0045bba6068cf31ac53852d6b743a745 68:true:c3b74bfc510dd2b4dc061217ff43eef6', (select string_agg(jobid||':'||active||':'||md5(command), ' ' order by jobid) from cron.job where jobid in (66,67,68))
)
select check_name, expected, actual, coalesce(expected = actual, false) pass from chk
union all select 'ALL POST-CHECKS PASS', 'true', (select bool_and(coalesce(expected=actual,false))::text from chk), (select bool_and(coalesce(expected=actual,false)) from chk);
